      jsx: true,
      children: `
        .about-page {
          overflow-x: hidden;
          background: linear-gradient(135deg, #0a1a2a 0%, #0a3d62 100%);
          color: #f0f8ff;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }

        /* Hero Section */
        .about-hero {
          position: relative;
          background: linear-gradient(rgba(0, 20, 40, 0.85), rgba(0, 20, 40, 0.85)), 
                      url('https://images.unsplash.com/photo-1593111774240-d529f12e5c4f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1770&q=80');
          background-size: cover;
          background-position: center;
          background-attachment: fixed;
          padding: 150px 0 120px;
          text-align: center;
          overflow: hidden;
        }

        .hero-overlay {
          position: absolute;
          top: 0;
          left: 0;
          width: 100%;
          height: 100%;
          background: radial-gradient(circle at center, rgba(10, 61, 98, 0.7) 0%, rgba(5, 30, 50, 0.9) 100%);
          z-index: 1;
        }

        .hero-content {
          position: relative;
          z-index: 2;
          padding: 40px;
          border-radius: 20px;
          background: rgba(5, 30, 50, 0.3);
          backdrop-filter: blur(5px);
          border: 1px solid rgba(100, 200, 255, 0.1);
        }

        .hero-title {
          font-size: 3.2rem;
          font-weight: 800;
          margin-bottom: 25px;
          position: relative;
          z-index: 2;
          text-shadow: 0 2px 10px rgba(0,0,0,0.5);
          background: linear-gradient(90deg, #88d498, #64c8fa);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          line-height: 1.2;
        }

        .hero-subtitle {
          font-size: 1.5rem;
          max-width: 700px;
          margin: 0 auto 30px;
          position: relative;
          z-index: 2;
          color: #e0f7ff;
          font-weight: 300;
        }

        .hero-icons {
          display: flex;
          justify-content: center;
          gap: 30px;
          margin-top: 30px;
        }

        .hero-icons .icon {
          font-size: 2.5rem;
          color: #64c8fa;
          transition: all 0.3s ease;
          animation: float 3s ease-in-out infinite;
        }

        .hero-icons .icon:nth-child(1) { animation-delay: 0s; }
        .hero-icons .icon:nth-child(2) { animation-delay: 0.5s; }
        .hero-icons .icon:nth-child(3) { animation-delay: 1s; }
        .hero-icons .icon:nth-child(4) { animation-delay: 1.5s; }

        .water-reflection {
          position: absolute;
          bottom: -10px;
          left: 0;
          width: 100%;
          height: 20px;
          background: linear-gradient(to bottom, rgba(100, 200, 255, 0.1), transparent);
          border-radius: 50%;
          filter: blur(5px);
          z-index: -1;
        }

        /* Glass Card Effect */
        .glass-card {
          background: rgba(255, 255, 255, 0.08);
          backdrop-filter: blur(12px);
          border: 1px solid rgba(100, 200, 255, 0.1);
          border-radius: 15px;
          overflow: hidden;
          box-shadow: 0 8px 32px rgba(0, 20, 40, 0.3);
          transition: all 0.4s ease;
          color: #e0f7ff;
        }

        .glass-card:hover {
          transform: translateY(-10px);
          box-shadow: 0 12px 40px rgba(0, 100, 200, 0.4);
          border: 1px solid rgba(100, 200, 255, 0.3);
        }

        /* Section Titles */
        .section-title {
          font-size: 2.6rem;
          font-weight: 800;
          position: relative;
          padding-bottom: 20px;
          color: #88d498;
          text-shadow: 0 2px 8px rgba(0,0,0,0.3);
        }

        .section-title::after {
          content: '';
          position: absolute;
          bottom: 0;
          left: 50%;
          transform: translateX(-50%);
          width: 100px;
          height: 5px;
          background: linear-gradient(90deg, #1a936f, #64c8fa);
          border-radius: 3px;
          box-shadow: 0 2px 10px rgba(26, 147, 111, 0.5);
        }

        /* Mission & Vision Cards */
        .mission-card .card-icon {
          background: linear-gradient(135deg, #1a936f, #88d498);
          box-shadow: 0 5px 15px rgba(26, 147, 111, 0.5);
        }

        .vision-card .card-icon {
          background: linear-gradient(135deg, #0a3d62, #64c8fa);
          box-shadow: 0 5px 15px rgba(10, 61, 98, 0.5);
        }

        .card-icon {
          width: 90px;
          height: 90px;
          display: flex;
          align-items: center;
          justify-content: center;
          border-radius: 50%;
          margin: -45px auto 25px;
          font-size: 2.5rem;
          color: white;
          position: relative;
          z-index: 2;
        }

        .card-title {
          font-size: 1.8rem;
          font-weight: 700;
          text-align: center;
          margin-bottom: 25px;
